let pts = [];
let onPressed = false
let showInstruction = true;
let f;

function setup() {
	createCanvas(windowWidth, windowHeight);
  colorMode(HSB);
  rectMode(CENTER);
  pts = [];
  background(255);
}

function draw() {
  if (onPressed) {
    for (let i=0;i<10;i++) {
      const newP = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), i+pts.length, i+pts.length);
      pts.push(newP);
    }
  }

  for (let i=pts.length-1; i>-1; i--) {
    const p = pts[i];
    if (p.dead) {
      pts.splice(i, 1);
    }else{
      p.update();
   	  p.display();
    }
  }
}

function mousePressed() {
  onPressed = true;
}

function mouseReleased() {
  onPressed = false;
}


// === Tab: Particle ===
class Particle {
  constructor(x, y, xOfst, yOfst){
    this.loc = createVector(x, y);

    const randDegrees = random(360);
    this.vel = createVector(cos(radians(randDegrees)), sin(radians(randDegrees)));
    this.vel.mult(random(5));

    this.acc = createVector(0,0);
    this.lifeSpan = int(random(30, 90));
    this.decay = random(0.75, 0.9);
    this.c = color(random(255),random(255), random(255));
    this.weightRange = random(3,50);
		this.passedLife = 0;

    this.xOfst = xOfst;
    this.yOfst = yOfst;
  }

  update () {
    if(this.passedLife>=this.lifeSpan){
      this.dead = true;
    }else{
      this.passedLife++;
    }

    this.alpha = (this.lifeSpan-this.passedLife)/this.lifeSpan * 70+50;
    this.weight = (this.lifeSpan-this.passedLife)/this.lifeSpan * this.weightRange;

    this.acc.set(0,0);

    const rn = (noise((this.loc.x+frameCount+this.xOfst)*0.01, (this.loc.y+frameCount+this.yOfst)*0.01)-0.5) * PI * 4;
    const mag = noise((this.loc.y-frameCount)*0.01, (this.loc.x-frameCount)*0.01);
    const dir = createVector(cos(rn),sin(rn));
    this.acc.add(dir);
    this.acc.mult(mag);

    const randRn = random(TWO_PI);
    const randV = createVector(cos(randRn), sin(randRn));
    randV.mult(0.25);
    this.acc.add(randV);

    this.vel.add(this.acc);
    this.vel.mult(this.decay);
    this.vel.limit(3);
    this.loc.add(this.vel);
  }

  display(){
		const colors = "d8f793-a0ca92-75b09c-998650-e0be36".split('-').map(c => '#' + c)
    strokeWeight(this.weight);
    stroke(colors[floor(random(colors.length))]);
    point(this.loc.x, this.loc.y);
  }
}

